const BAGHA_JATIN_INFO={id:"bagha-jatin",title:"Jatindranath Mukherjee (Bagha Jatin)",quickStats:[{label:"Born",value:"1879, Kaya, Bengal",icon:"📍"},{label:"Died",value:"1915, Balasore",icon:"🕯️"},{label:"Title",value:'"Bagha Jatin" (Tiger Jatin)',icon:"🐅"},{label:"Movement",value:"Jugantar & Bengal Revolutionary Network",icon:"🇮🇳"},{label:"Key Event",value:"Battle of Balasore, 1915",icon:"📜"},{label:"Legacy",value:"Central Figure of Bengal's Armed Movement",icon:"🌟"}]},HISTORY_TEXT={title:"From Physical Culture to Revolutionary Leadership",paragraphs:["Jatindranath Mukherjee, popularly known as Bagha Jatin ('Tiger Jatin'), was born in 1879 in Kaya village, Bengal Presidency. He earned his nickname after a widely recounted incident in which he killed a tiger that attacked him, becoming known for his exceptional physical strength and courage from a young age.","Mukherjee became one of the central organizing figures of Bengal's early 20th-century revolutionary movement, associated with the Jugantar group, which emerged from the broader Swadeshi-era nationalist ferment following the 1905 partition of Bengal.","He built and led an extensive network of revolutionary contacts across Bengal and beyond, and during the First World War period, sought international support — including contact with German representatives — for anti-colonial activity, reflecting the movement's efforts to draw on the geopolitical tensions of the war.","In September 1915, Jatindranath Mukherjee and several associates were confronted by British colonial police and military forces near Balasore, in present-day Odisha, in what became known historically as the Battle of Balasore. He was fatally wounded in the encounter and died shortly after. He is remembered today as one of the most significant leaders of Bengal's revolutionary movement in the early 20th century."]},TIMELINE_EVENTS=[{era:"1879",title:"Born in Kaya, Bengal",description:"Jatindranath Mukherjee was born into a Bengali family in Kaya village."},{era:"Early 1900s",title:"The 'Bagha Jatin' Legend",description:"Became known as 'Bagha Jatin' following a widely recounted incident demonstrating his physical courage."},{era:"1905 onward",title:"Rise of the Swadeshi Movement",description:"The partition of Bengal in 1905 fueled a wave of nationalist and revolutionary organizing that Mukherjee became part of."},{era:"1900s–1910s",title:"Leadership in the Jugantar Group",description:"Emerged as a central organizing figure within Bengal's revolutionary network associated with the Jugantar movement."},{era:"1914–15",title:"Wartime Organizing",description:"During World War I, sought international connections to support the movement's anti-colonial aims."},{era:"September 1915",title:"Battle of Balasore",description:"Confronted by British colonial forces near Balasore; fatally wounded in the encounter."},{era:"1915",title:"Death",description:"Jatindranath Mukherjee died shortly after the Balasore encounter, becoming a lasting symbol of Bengal's revolutionary movement."}],NETWORK_POINTS=[{title:"The Jugantar Group",description:"A major Bengal-based revolutionary organization that emerged from Swadeshi-era nationalist activity, of which Mukherjee was a central leader."},{title:"Regional Organizing Network",description:"Built and coordinated a wide network of revolutionary contacts and sympathizers across Bengal and neighboring regions."},{title:"International Outreach",description:"During World War I, the movement sought international support, reflecting broader efforts by Indian revolutionaries abroad and at home to leverage wartime geopolitics."},{title:"Mentorship of Younger Revolutionaries",description:"Historical accounts describe Mukherjee as an influential figure who inspired and guided a generation of younger nationalists in Bengal."}],LEGACY_TEXT={paragraphs:["Jatindranath Mukherjee is remembered as one of the most significant leaders of Bengal's early 20th-century revolutionary movement, admired historically for his organizational leadership, personal courage, and the scale of the network he helped build. The 'Bagha Jatin' name endures in regional memory as a symbol of fearless resistance.","His life and the events at Balasore are commemorated in Odisha and West Bengal through memorials, and his story remains a significant part of the historical narrative of India's armed revolutionary movement in the years leading up to broader 20th-century independence efforts."]},GALLERY_QUERIES=["Balasore Odisha historical site","Bengal Presidency early 20th century","Kolkata colonial era architecture"],REFERENCES=[{text:"Government of West Bengal — historical records on the Jugantar movement.",link:"#"},{text:"Heehs, P. — 'The Bomb in Bengal: The Rise of Revolutionary Terrorism in India, 1900–1910.'",link:"#"},{text:"Government of Odisha — historical documentation of the Balasore encounter.",link:"#"},{text:"Academic histories of the Bengal revolutionary movement, 1900s–1910s.",link:"#"}];